  /// older row mutates across frames — a frozen transcript must never
  /// show moving counts. Keys are bounded by the card-history cap.
  final Map<int, String> _frozenOlderSummaries = {};

  /// Cards that reload demoted from live to lost — they still owe the
  /// transcript a terminal card.
  final Set<String> _pendingResumeLost = {};

  /// The current turn bucket. Starts at 1; [newTurn] advances it at each
  /// agent-run boundary.
  int turn;

  /// Advance to the next turn bucket (age-out: old buckets stop emitting).
  void newTurn() => turn++;

  /// Register a started job. The card's state must be live; [turn] is
  /// stamped by the board. The in-memory history stays capped at
  /// [_maxBoardHistory] (the documented invariant — month-long sessions
  /// must not accumulate every card ever).
  void start(TaskBlock card) {
    _cards.add(
      TaskBlock(
        id: card.id,
        kind: card.kind,
        label: card.label,
        state: card.state == TaskBlockState.running
            ? TaskBlockState.running
