/// a freshly minted uuid per parse was unaddressable and round-trip
/// unstable).
String stableEntryId({
  required String sourceRecordId,
  required String kind,
  required String text,
}) => 'obl-${_fnv1a('$sourceRecordId|$kind|$text')}';

