      // 100000 - 16384 = 83616; strictly greater required (pi semantics).
      expect(shouldCompact(83616, 100000, defaultCompactionSettings), isFalse);
      expect(shouldCompact(83617, 100000, defaultCompactionSettings), isTrue);
    });
