      textTurn('answered after degraded boot'),
    ]);
    final agent = cli(env, stream);

    final run = agent.run();
    await waitForIt(
      () => stream.calls >= 1 && !agent.isBusy,
      reason: 'the failed cap attempt settles at boot',
