final class _FakeShellJob implements ShellJob {
  _FakeShellJob(this.id, this.command, this.logPath, this._env);

  final MemoryExecutionEnv _env;
  final _output = StreamController<String>.broadcast();
  final _settled = Completer<void>();
  int? _exitCode;
  String? _stopReason;

  @override
  final String id;
  @override
  final String command;
  @override
  final String logPath;
  @override
  int? get pid => null;
  @override
  bool get isRunning => _exitCode == null;
  @override
  int? get exitCode => _exitCode;
  @override
  String? get stopReason => _stopReason;
  @override
  Future<void> get settled => _settled.future;
  @override
  Stream<String> get output => _output.stream;
  @override
  bool writeStdin(String data) => true;
  @override
  Future<void> stop() async {
    _stopReason = 'stopped';
    complete(143);
  }

  void complete(int code, {String? reason}) {
    if (_exitCode != null) return;
    _stopReason = reason;
    _exitCode = code;
    _settled.complete();
  }
}

/// MemoryExecutionEnv wrapper with the [BackgroundShell] capability.
final class _FakeBackgroundEnv implements ExecutionEnv, BackgroundShell {
  _FakeBackgroundEnv(this._delegate);

  final MemoryExecutionEnv _delegate;
  final jobs = <_FakeShellJob>[];

  @override
  bool get backgroundJobsSupported => true;
  @override
  Future<Result<ShellJob, ExecutionError>> startShellJob(
    String command, {
    required String id,
    required String logPath,
    ShellExecOptions? options,
  }) async {
    final job = _FakeShellJob(id, command, logPath, _delegate);
    jobs.add(job);
    return Ok(job);
  }

  @override
  String get cwd => _delegate.cwd;
  @override
  Future<Result<void, FileError>> createDir(
    String path, {
    bool recursive = true,
  }) => _delegate.createDir(path, recursive: recursive);
  @override
  Future<Result<String, FileError>> readTextFile(
    String path, {
    int? offset,
    int? count,
  }) => _delegate.readTextFile(path, offset: offset, count: count);
  @override
  Future<Result<List<FileInfo>, FileError>> listDir(String path) =>
      _delegate.listDir(path);
  @override
  Future<Result<String, FileError>> appendFile(String path, String content) =>
      _delegate.appendFile(path, content);
  @override
  Future<Result<String, FileError>> writeFile(String path, String content) =>
      _delegate.writeFile(path, content);
  @override
  Future<Result<void, FileError>> removePath(
    String path, {
    bool recursive = false,
  }) => _delegate.removePath(path, recursive: recursive);
}

