String _longPipeline(int chars, int seed) {
  final buffer = StringBuffer('cd /app && python3 mips.py --trace --dump ');
  while (buffer.length < chars) {
    buffer.write('x$seed');
  }
  return buffer.toString().substring(0, chars);
}

