{"content":"// gh-1604 item 4 — the bench env knob for the tool-output cap.
//
// The spill pipeline (issue #678) already caps single tool outputs at M
// chars with a `[... N chars omitted ...]` marker and a read-the-spill-file
// affordance — but it only attaches when a `spills:` yaml section exists.
// Bench runs configure through the environment:
// `FAH_SPILL_THRESHOLD` enables/tunes the cap for one run (and `0`
// explicitly disables it), without touching any config file.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  group('resolveRunSpillsConfig (gh-1604 item 4)', () {
    test('no section + no env → null (legacy: hook not attached)', () {
      expect(resolveRunSpillsConfig(null, {}), isNull);
    });

    test('no section + env set → enabled with the env threshold', () {
      final config = resolveRunSpillsConfig(null, {
        spillThresholdEnvVar: '4096',
      });
      expect(config, isNotNull);
      expect(config!.isActive, isTrue);
      expect(config.threshold, 4096);
      // The preview bounds stay the shared defaults.
      expect(config.headChars, 2000);
      expect(config.tailChars, 2000);
    });

    test('env wins over the configured threshold', () {
      final config = resolveRunSpillsConfig(
        const SpillsConfig(threshold: 8192),
        {spillThresholdEnvVar: '2048'},
      );
      expect(config!.threshold, 2048);
    });

    test('env 0 explicitly disables a configured section', () {
      final config = resolveRunSpillsConfig(
        const SpillsConfig(threshold: 8192),
        {spillThresholdEnvVar: '0'},
      );
      expect(config!.isActive, isFalse);
    });

    test('junk env is ignored — the config applies untouched', () {
      final section = const SpillsConfig(threshold: 8192);
      expect(
        resolveRunSpillsConfig(section, {spillThresholdEnvVar: 'big'}),
        same(section),
      );
      expect(resolveRunSpillsConfig(null, {spillThresholdEnvVar: 'big'}),
          isNull);
    });

    test('the full end-to-end preview shape still holds under the env cap',
        () {
      final config = resolveRunSpillsConfig(null, {
        spillThresholdEnvVar: '1000',
      })!;
      expect(shouldSpill('x' * 1001, config), isTrue);
      expect(shouldSpill('x' * 1000, config), isFalse);
      final preview = buildPreview(
        'h' * 600 + 'm' * 300 + 't' * 600,
        spillPath: '.fah/spills/s/1.txt',
        config: config,
      );
      expect(preview, contains('[... 300 chars omitted ...]'));
      expect(preview, contains('[read the spill file above'));
    });
  });
}
","path":"test/spill/spill_env_test.dart"}

{"newText":"/// The smallest preview excerpt bound accepted from config. A section
/// asking for less is clamped up to this (with a note) so a preview can
/// never degenerate into a single unreadable line (issue #678 AC11).
const spillsMinPreviewChars = 200;

/// The env var a bench/unattended run sets to enable/tune the tool-output
/// cap for ONE run without any config file (gh-1604 item 4): a positive
/// integer is the spill threshold in chars; `0` explicitly disables.
/// Unset or junk leaves the configured section untouched.
const spillThresholdEnvVar = 'FAH_SPILL_THRESHOLD';

/// Resolves the run's spills config from the yaml [section] (null when
/// the config files carry no `spills:`) plus the [env] knob
/// ([spillThresholdEnvVar]). Pure:
///
/// - section absent + env unset → null — the hook is never attached, the
///   byte-identical legacy shape (issue #678 AC1);
/// - env set to a positive int → enabled with THAT threshold (env wins
///   over the configured threshold; preview bounds stay the defaults);
/// - env `0` → explicitly disabled for this run;
/// - env junk → ignored (the section applies untouched; junk never
///   breaks a boot).
SpillsConfig? resolveRunSpillsConfig(
  SpillsConfig? section,
  Map<String, String> env,
) {
  final value = int.tryParse(env[spillThresholdEnvVar]?.trim() ?? '');
  if (value == null) return section;
  if (value <= 0) return const SpillsConfig(enabled: false);
  final base = section ?? const SpillsConfig();
  return SpillsConfig(
    enabled: true,
    threshold: value,
    headChars: base.headChars,
    tailChars: base.tailChars,
  );
