{"content":"// gh-1604 items 2+3 — the bench-profile auto-compaction trigger.
//
// `FAH_COMPACT_TRIGGER_TOKENS` lowers the auto-compaction trigger to an
// absolute context size for bench/unattended runs: summarization fires
// when the estimated context exceeds the trigger, long before the
// window-minus-reserve default, keeping the task text + a rolling summary
// instead of letting the model-visible stream accrete for a whole
// 30-minute trial.
//
// AC3 (mechanism): the trigger is pure, clamped, and byte-identical when
// the env is unset.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  group('benchCompactionTriggerTokens', () {
    test('unset env → null (byte-identical legacy behavior)', () {
      expect(benchCompactionTriggerTokens({}), isNull);
      expect(benchCompactionTriggerTokens({
        'FAH_COMPACT_TRIGGER_TOKENS': '',
      }), isNull);
      expect(benchCompactionTriggerTokens({
        'FAH_COMPACT_TRIGGER_TOKENS': '   ',
      }), isNull);
    });

    test('a positive integer parses', () {
      expect(benchCompactionTriggerTokens({
        'FAH_COMPACT_TRIGGER_TOKENS': '80000',
      }), 80000);
      expect(benchCompactionTriggerTokens({
        'FAH_COMPACT_TRIGGER_TOKENS': ' 6000 ',
      }), 6000);
    });

    test('junk, zero and negative values are ignored (null)', () {
      for (final value in ['abc', '0', '-5', '8.000', '80 000']) {
        expect(
          benchCompactionTriggerTokens({
            'FAH_COMPACT_TRIGGER_TOKENS': value,
          }),
          isNull,
          reason: value,
        );
      }
    });
  });

  group('withCompactionTriggerTokens', () {
    const window = 200000;
    final base = CompactionSettings.forWindow(window);

    test('a trigger below the default threshold raises the reserve so the '
        'trigger becomes the firing point', () {
      final settings = withCompactionTriggerTokens(
        base,
        window: window,
        triggerTokens: 80000,
      );
      expect(shouldCompact(80000, window, settings), isFalse);
      expect(shouldCompact(80001, window, settings), isTrue);
      // The kept region never eats more than half the trigger: a pass
      // always frees tokens.
      expect(
        settings.keepRecentTokens,
        lessThanOrEqualTo(settings.reserveTokens),
      );
      expect(settings.enabled, isTrue);
    });

    test('the default 20k keep budget yields to the trigger cap', () {
      final settings = withCompactionTriggerTokens(
        base,
        window: window,
        triggerTokens: 6000,
      );
      expect(settings.keepRecentTokens, lessThanOrEqualTo(3000));
      expect(shouldCompact(6000, window, settings), isFalse);
      expect(shouldCompact(6001, window, settings), isTrue);
    });

    test('a trigger at/above the default threshold is a no-op', () {
      final defaultTrigger = window - base.reserveTokens;
      final settings = withCompactionTriggerTokens(
        base,
        window: window,
        triggerTokens: defaultTrigger,
      );
      expect(settings.reserveTokens, base.reserveTokens);
      expect(settings.keepRecentTokens, base.keepRecentTokens);
    });

    test('out-of-range triggers clamp into the window', () {
      // Above the window: clamped to just under it — compaction would
      // fire essentially at the window, never past it.
      final high = withCompactionTriggerTokens(
        base,
        window: window,
        triggerTokens: window * 2,
      );
      expect(shouldCompact(window - 1, window, high), isFalse);
      expect(shouldCompact(window, window, high), isTrue);
    });
  });

  group('resolveBenchCompactionSettings', () {
    test('env unset → the base settings, byte-identical', () {
      final base = CompactionSettings.forWindow(200000);
      expect(
        resolveBenchCompactionSettings(base, window: 200000, env: {}),
        same(base),
      );
    });

    test('env set → the trigger-applied settings', () {
      final settings = resolveBenchCompactionSettings(
        CompactionSettings.forWindow(200000),
        window: 200000,
        env: {'FAH_COMPACT_TRIGGER_TOKENS': '64000'},
      );
      expect(shouldCompact(64000, 200000, settings), isFalse);
      expect(shouldCompact(64001, 200000, settings), isTrue);
    });
  });
}
","path":"test/compaction/bench_trigger_test.dart"}

{"content":"/// The bench-profile auto-compaction trigger (gh-1604 items 2+3).
///
/// Long bench trials (30-minute MIPS-class tasks) never trip the
/// window-minus-reserve default: the context grows monotonically, every
/// later request re-reads the accreted stream, and a single trial burned
/// 11.2M input tokens. The bench env knob
/// (`FAH_COMPACT_TRIGGER_TOKENS`) lowers the auto-compaction trigger to
/// an ABSOLUTE context size — summarization fires as soon as the
/// estimated context crosses it, keeping the task text + a rolling
/// summary, so the per-request context stays bounded for the whole run.
///
/// Pure Dart: the env map is injected (the CLI passes
/// `Platform.environment`, tests pass their own), no dart:io.
library;

import 'compaction.dart';

/// The env var a bench/unattended run sets to bound the context: the
/// auto-compaction trigger becomes this many estimated tokens instead of
/// the window-minus-reserve default. Unset/blank/invalid = the default
/// behavior, byte-identical.
const benchCompactionTriggerEnvVar = 'FAH_COMPACT_TRIGGER_TOKENS';

/// The [benchCompactionTriggerEnvVar] value from [env] as a positive
/// integer, trimmed; null when unset, blank, or not a positive integer
/// (junk never breaks a boot — the default behavior applies). Pure.
int? benchCompactionTriggerTokens(Map<String, String> env) {
  final value = env[benchCompactionTriggerEnvVar]?.trim();
  if (value == null || value.isEmpty) return null;
  final parsed = int.tryParse(value);
  return (parsed != null && parsed > 0) ? parsed : null;
}

/// Applies [triggerTokens] as the compaction firing point to [base] for a
/// model whose (effective) context window is [window].
///
/// The trigger of [CompactionSettings] is `window - reserveTokens`
/// ([shouldCompact]); reaching trigger [triggerTokens] therefore raises
/// the reserve to `window - triggerTokens`. Two guards keep the pass
/// sane:
///
/// - the kept recent region never exceeds half the trigger — a pass
///   always frees tokens, never reshuffles the same budget;
/// - a trigger at/above the settings' own default threshold is a no-op
///   (the bench knob can only LOWER the trigger, never raise it);
/// - a trigger at/above the window clamps to `window` (fire at the
///   window, never past it).
///
/// Pure; returns [base] unchanged when the trigger changes nothing.
CompactionSettings withCompactionTriggerTokens(
  CompactionSettings base, {
  required int window,
  required int triggerTokens,
}) {
  if (!base.enabled) return base;
  final clamped = triggerTokens.clamp(1, window);
  final defaultTrigger = window - base.reserveTokens;
  if (clamped >= defaultTrigger) return base;
  final keep = base.keepRecentTokens.clamp(1, clamped ~/ 2);
  return CompactionSettings(
    enabled: true,
    reserveTokens: window - clamped,
    keepRecentTokens: keep,
  );
}

/// Composes [benchCompactionTriggerTokens] over [base]: the settings the
/// host's compaction gate should use for this run. The env-unset case
/// returns [base] IDENTICALLY (same instance) so unset runs stay
/// byte-for-byte legacy. Pure.
// ignore: unnecessary_this
CompactionSettings resolveBenchCompactionSettings(
  CompactionSettings base, {
  required int window,
  required Map<String, String> env,
}) {
  final trigger = benchCompactionTriggerTokens(env);
  if (trigger == null) return base;
  return withCompactionTriggerTokens(base, window: window, triggerTokens: trigger);
}
","path":"lib/src/compaction/bench_trigger.dart"}

