List<AssistantMessageEvent> textTurn(String text, {Usage? usage}) {
  final empty = testAssistant();
  final partial = testAssistant(
    content: [TextContent(text: text)],
    usage: usage,
  );
  return [
    StartEvent(partial: empty),
    TextStartEvent(contentIndex: 0, partial: empty),
    TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
    DoneEvent(reason: StopReason.stop, message: partial),
  ];
}

List<AssistantMessageEvent> toolTurn(List<ToolCall> calls) {
  final empty = testAssistant();
  final partial = testAssistant(content: calls, stopReason: StopReason.toolUse);
  final events = <AssistantMessageEvent>[StartEvent(partial: empty)];
  for (var i = 0; i < calls.length; i++) {
    events
      ..add(ToolCallStartEvent(contentIndex: i, partial: empty))
      ..add(
        ToolCallEndEvent(contentIndex: i, toolCall: calls[i], partial: partial),
      );
  }
  events.add(DoneEvent(reason: StopReason.toolUse, message: partial));
  return events;
}

/// The text of a user message (string or content-block content) — the
/// shared assertion helper for outbound prompts (issue #1152).
String messageText(UserMessage message) {
  final content = message.content;
  if (content is String) return content;
  return [
    for (final block in content as List<ContentBlock>)
      if (block is TextContent) block.text,
  ].join();
}

/// Scripted [StreamFunction] replaying pre-recorded turns.
class FakeStreamFunction {
  FakeStreamFunction(this.turns);

  final List<List<AssistantMessageEvent>> turns;
  final contexts = <Context>[];
  final models = <Model>[];

  int get calls => contexts.length;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    models.add(model);
    contexts.add(
      Context(
        systemPrompt: context.systemPrompt,
        messages: List.of(context.messages),
        tools: context.tools,
      ),
    );
    final stream = AssistantMessageEventStream();
    for (final event in turns.removeAt(0)) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }
}

final class ToolResultMessage implements Message {
  const ToolResultMessage({
    required this.toolCallId,
    required this.toolName,
    required this.content,
    required this.isError,
    required this.timestamp,
  });

  /// The [ToolCall.id] this result answers.
  final String toolCallId;

  /// The name of the tool that produced this result.
  final String toolName;

  /// Result content: text and/or images.
  final List<ContentBlock> content;

  /// Whether the tool execution failed.
  final bool isError;

  @override
  final DateTime timestamp;

  @override
  String get role => 'toolResult';

  @override
  Map<String, dynamic> toJson() => {
    'role': role,
    'toolCallId': toolCallId,
    'toolName': toolName,
    'content': content.map((block) => block.toJson()).toList(),
    'isError': isError,
    'timestamp': timestamp.millisecondsSinceEpoch,
  };

  /// Deserializes from a JSON map produced by [toJson].
  factory ToolResultMessage.fromJson(Map<String, dynamic> json) =>
      ToolResultMessage(
        toolCallId: json['toolCallId'] as String? ?? '',
        toolName: json['toolName'] as String? ?? '',
        content: [
          for (final block in (json['content'] as List?) ?? const [])
            ContentBlock.fromJson(block as Map<String, dynamic>),
        ],
        isError: json['isError'] as bool? ?? false,
        timestamp: DateTime.fromMillisecondsSinceEpoch(
          json['timestamp'] as int? ?? 0,
        ),
      );
}

/// Deserializes a [Message] from its JSON map, dispatching on `role`.
Message messageFromJson(Map<String, dynamic> json) {
  return switch (json['role']) {
    'user' => UserMessage.fromJson(json),
    'assistant' => AssistantMessage.fromJson(json),
    'toolResult' => ToolResultMessage.fromJson(json),
    _ => throw FormatException('Unknown message role: ${json['role']}'),
  };
}

