      file.writeAsStringSync('compaction:\n  engine: turbo\n');
      expect(
        () => loadProjectCompactionEngine(dir.path),
        throwsA(isA<ConfigException>()),
      );
    } finally {
      dir.deleteSync(recursive: true);
    }
  });

