      expect(firstRequestTokens, lessThanOrEqualTo(_defaultTrigger));

      io.sendLine('go again');
      await waitForIt(
        () => stream.calls >= 3 && !agent.isBusy,
        reason: 'the compaction pass runs and the second turn answers',
      );
      io.sendLine('/exit');
