          'kind': 'owner-rule',
          'text': ledgerText,
          'sourceRecordId': 'rec-1',
          'createdAt': DateTime.utc(2026).toIso8601String(),
          'status': 'open',
        },
      ],
    );
    // A valid tool pair: the call, then the result.
    await seed.appendMessage(
      AssistantMessage(
        content: [
