        toolCallId: 'call-seed-1',
        toolName: 'read',
        content: [const TextContent(text: 'latest seed tool result')],
        isError: false,
        timestamp: DateTime.utc(2026),
      ),
    );
    // Filler: 12 × ~1000 chars ≈ 3000 estimated tokens … plus the records
