    groups,
    over,
    protectedTailIds(view.ledger, protectLastN),
    view.state.pinnedRecordIds,
  );
  if (evictions.isEmpty) return;
  await session.appendHiddenRange(recordIds: evictions.toList()..sort());
  final after = await _refreshState();
