  if (view == null) return;
  final groups = _rehideCandidates(view);
  if (groups.length <= 1) return;
  final evictions = _pickRehideEvictions(
    groups,
    over,
    protectedTailIds(view.ledger, protectLastN),
    view.state.pinnedRecordIds,
  );
  if (evictions.isEmpty) return;
