    StructuredCompactionPass(
      kind: 'hide-lru',
      pass: ++_pass,
      tokensBefore: before,
      tokensAfter: after,
      ok: true,
      judgeCalls: 0,
      hiddenCount: evictions.length,
    ),
  );
}

