int _depthOf(
  CompactCheckpointRecord ckpt,
  Map<String, CompactCheckpointRecord> byId,
  Set<String> visiting,
) {
  if (!visiting.add(ckpt.id)) return 1; // Cycle defense: treat as leaf.
  var depth = 1;
  for (final id in ckpt.coversRecordIds) {
