    if (inner == null) continue;
    if (ckpt.flattenedRecordIds.contains(id)) continue; // Dead node.
    final innerDepth = _depthOf(inner, byId, visiting);
    if (innerDepth + 1 > depth) depth = innerDepth + 1;
  }
  visiting.remove(ckpt.id);
  return depth;
}

