      reply = _checkpointReply;
    } else {
      reply = answers[_answered++ % answers.length];
    }
    final stream = AssistantMessageEventStream();
    for (final event in textTurn(reply)) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }
}

