    final repo = _repo;
    if (repo is JsonlSessionRepo) {
      final reports = await repo.readCustomRecordsOfType(metadata, {
        orphanReportRecordType,
      }, lastSegmentOnly: true);
      _agent.reportedOrphanKeys
        ..clear()
        ..addAll(orphanReportKeysFromRecords(reports));
