int? _hideableGroupTokens(
  Map<String, int> tokensById,
  Iterable<String> group,
  Set<String> protectedTail,
) {
  var groupTokens = 0;
  for (final id in group) {
    if (protectedTail.contains(id)) return null;
    groupTokens += tokensById[id] ?? 0;
  }
  return groupTokens;
}

