/// endpoint of the dead call — never an anonymous TimeoutException.
TimeoutException _judgeTimeout() => TimeoutException(
  'structured compaction judge timeout '
  '($judgeTarget, ${attemptBudget.inSeconds}s budget) (issue #515)',
  attemptBudget,
);

