  /// `'hide'` or `'checkpoint'`.
  final String kind;

  /// 1-based pass number within the run.
  final int pass;

  /// Estimated tokens before the pass.
  final int tokensBefore;

  /// Estimated tokens after the pass.
  final int tokensAfter;

  /// Whether the pass appended state.
