      prompts: prompts,
      maxPasses: maxPasses,
      maxAttempts: maxAttempts,
      baseBackoff: baseBackoff,
      force: force,
      attemptBudget: attemptBudget,
      totalBudget: totalBudget,
      runToken: runToken,
      operativeSkills: operativeSkills,
