  ToolResultMessage() =>
    m.content.whereType<TextContent>().map((b) => b.text).join('\n'),
  _ => '',
};

/// A value snapshot of a rendered view — roles + flattened text.
List<(String, String)> _shapeOf(List<Message> messages) => [
  for (final m in messages) (m.role, _textOf(m)),
];

