    final compactor = StructuredCompactor(
      session: session,
      state: state,
      window: 32768,
      settings: settings,
      judge: (ledgerText) async {
        // ignore: avoid_print
        print('JUDGE ledgerLen=${ledgerText.length}');
        return '[]';
      },
      summarize: (request) async {
        // ignore: avoid_print
        print('SUMMARIZE promptLen=${request.prompt.length} '
