    for (final e in await session.getEntries()) {
      if (e is CompactCheckpointRecord) {
        // ignore: avoid_print
        print('CKPT covers=${e.coversRecordIds.length} '
            'text=${e.text.substring(0, 30)}');
      }
    }
  });
