      final config = resolveRunSpillsConfig(
        const SpillsConfig(threshold: 8192),
        {spillThresholdEnvVar: '2048'},
      );
      expect(config!.threshold, 2048);
    });

    test('env 0 explicitly disables a configured section', () {
      final config = resolveRunSpillsConfig(
        const SpillsConfig(threshold: 8192),
        {spillThresholdEnvVar: '0'},
