    // instead of splitting it: no half a pair ever dangles at a cut.
    expect(label.startsWith('a' * 119), isTrue);
    expect(
      label.startsWith('a' * 119 + String.fromCharCode(0xDC00)),
      isFalse,
    );
  });
});

